//! A price series, and the gate everything derived has to pass through.
//!
//! This is `reconcile` for market data, and it exists for the same reason: arithmetic over a series
//! that is subtly wrong does not produce an error, it produces A BACKTEST THAT LOOKS GOOD. Every way
//! a price series lies is a way a strategy appears profitable, and none of them announce themselves.
//!
//! # The four that matter, in the order they cost you money
//!
//! 1. **Look-ahead.** Deciding a trade on a bar you could not have seen yet. Using today's CLOSE to
//!    choose today's entry is the single most common backtest bug and it is invisible, because the
//!    equity curve it produces is beautiful. [`bars_available_at`] is the whole answer: it hands back
//!    only bars STRICTLY BEFORE the decision date, so the wrong thing is awkward to write rather
//!    than merely discouraged.
//! 2. **Survivorship.** A universe of "the stocks that exist today" backtested over ten years has
//!    silently excluded everything that went to zero. The bias is enormous and invisible in the data
//!    — nothing in a series says what is missing from it. So it is DECLARED, never inferred, and a
//!    universe-level claim on a series that has not declared it is refused.
//! 3. **Corporate actions.** An unadjusted series shows a 2-for-1 split as a −50% day. A strategy
//!    that buys drops finds a great many of them.
//! 4. **Stale and missing bars.** A feed repeating its last value looks exactly like zero
//!    volatility, which is a wonderful thing to be short. A missing day is a hole a strategy steps
//!    over without noticing.
use crate::money::{money, Currency, Money};

/// One bar. Prices are integer MINOR UNITS at the series' declared scale — never floats.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bar {
    /// `YYYY-MM-DD`.
    pub date_i: BarDate,
    pub open: Money,
    pub high: Money,
    pub low: Money,
    pub close: Money,
    /// Share/contract count. ABSENT means the source did not carry it — not zero.
    pub volume: Option<i64>,
}

/// A `YYYY-MM-DD` held inline so a `Bar` stays `Copy`.
///
/// Ten ASCII bytes, which every ISO date is. A shorter string is padded and compares equal to what
/// it was, so nothing silently becomes a different date.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct BarDate([u8; 10]);

impl BarDate {
    pub fn new(s: &str) -> BarDate {
        let mut b = [b' '; 10];
        for (i, c) in s.bytes().take(10).enumerate() {
            b[i] = c;
        }
        BarDate(b)
    }

    pub fn as_str(&self) -> &str {
        std::str::from_utf8(&self.0).unwrap_or("??????????").trim_end()
    }
}

impl std::fmt::Display for BarDate {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl Bar {
    pub fn date(&self) -> &str {
        self.date_i.as_str()
    }
}

/// What the CALLER asserts about where the series came from. None of this is inferable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SeriesMeta {
    pub symbol: String,
    /// Split- and dividend-adjusted. NONE means nobody said, which is not the same as false.
    pub adjusted: Option<bool>,
    /// The universe this came from includes delisted names. NONE means nobody said.
    pub survivorship_free: Option<bool>,
    pub source: String,
    /// Minor units per whole unit of price — 100 for cents. DECLARED, because an option quoted in
    /// hundredths of a cent and an equity quoted in cents are both "integers".
    pub minor_per_unit: i64,
}

impl SeriesMeta {
    pub fn new(symbol: &str, source: &str) -> SeriesMeta {
        SeriesMeta { symbol: symbol.to_string(), adjusted: None, survivorship_free: None, source: source.to_string(), minor_per_unit: 100 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SeriesProblemKind {
    OutOfOrder,
    Duplicate,
    NonPositive,
    ImpossibleBar,
    Gap,
    Stale,
    ProbableCorporateAction,
}

impl SeriesProblemKind {
    pub fn label(self) -> &'static str {
        match self {
            SeriesProblemKind::OutOfOrder => "out-of-order",
            SeriesProblemKind::Duplicate => "duplicate",
            SeriesProblemKind::NonPositive => "non-positive",
            SeriesProblemKind::ImpossibleBar => "impossible-bar",
            SeriesProblemKind::Gap => "gap",
            SeriesProblemKind::Stale => "stale",
            SeriesProblemKind::ProbableCorporateAction => "probable-corporate-action",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SeriesProblem {
    pub kind: SeriesProblemKind,
    pub at: String,
    pub detail: String,
}

/// A series something has actually checked.
///
/// EVERY FIELD IS PRIVATE, so only [`check_series`] and the deliberately-named [`unverified_series`]
/// can produce one and a backtest asking for a `VerifiedSeries` cannot be handed a raw vector. The
/// same mechanism as `ReconciledLedger`, for the same reason — and in Rust a private field is a
/// strictly stronger brand than the TypeScript's phantom symbol, which a cast can forge.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VerifiedSeries {
    bars: Vec<Bar>,
    meta: SeriesMeta,
    unverified: bool,
    caveat: Option<String>,
}

impl VerifiedSeries {
    pub fn bars(&self) -> &[Bar] {
        &self.bars
    }

    pub fn meta(&self) -> &SeriesMeta {
        &self.meta
    }

    /// True when this came from [`unverified_series`] rather than a passing check.
    pub fn unverified(&self) -> bool {
        self.unverified
    }

    pub fn caveat(&self) -> Option<&str> {
        self.caveat.as_deref()
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SeriesCheck {
    pub ok: bool,
    pub series: Option<VerifiedSeries>,
    pub problems: Vec<SeriesProblem>,
}

pub struct CheckOptions<'a> {
    /// Trading days the market was closed. Without one, a holiday reads as a gap — the check SAYS SO
    /// rather than pretending it can tell them apart.
    pub holidays: &'a [String],
    /// Identical closes in a row before it is called stale.
    pub stale_run: usize,
    /// A single-day move at or beyond this, in an UNADJUSTED series, reads as a corporate action.
    pub split_move: f64,
}

impl Default for CheckOptions<'_> {
    fn default() -> Self {
        CheckOptions { holidays: &[], stale_run: 5, split_move: 0.4 }
    }
}

/// Saturday or Sunday.
///
/// PUBLIC because a synthetic calendar and the gap check must not be able to disagree about which
/// days a market is open — two definitions of a trading day is two answers to the same question.
pub fn is_weekend(iso: &str) -> bool {
    match crate::session::epoch_seconds(&format!("{iso}T00:00:00Z")) {
        // 1970-01-01 was a THURSDAY, so day 0 is index 4 in a Sunday-first week.
        Some(secs) => matches!((secs.div_euclid(86_400) + 4).rem_euclid(7), 0 | 6),
        None => false,
    }
}

fn next_day(iso: &str) -> String {
    crate::obligations::add_days(iso, 1)
}

/// Check a series, and mint a [`VerifiedSeries`] only if nothing is wrong with it.
pub fn check_series(bars: &[Bar], meta: SeriesMeta, opts: &CheckOptions) -> SeriesCheck {
    let mut problems: Vec<SeriesProblem> = Vec::new();

    for (i, b) in bars.iter().enumerate() {
        let prev = if i > 0 { Some(&bars[i - 1]) } else { None };

        if let Some(p) = prev {
            if b.date_i == p.date_i {
                problems.push(SeriesProblem { kind: SeriesProblemKind::Duplicate, at: b.date().to_string(), detail: "two bars share one date".to_string() });
            } else if b.date_i < p.date_i {
                problems.push(SeriesProblem { kind: SeriesProblemKind::OutOfOrder, at: b.date().to_string(), detail: format!("follows {}", p.date()) });
            }
        }

        if [b.open, b.high, b.low, b.close].iter().any(|p| p.minor <= 0) {
            // A zero or negative price is not a price. It is a parse failure or a padded row, and a
            // return computed across one is arbitrarily large.
            problems.push(SeriesProblem { kind: SeriesProblemKind::NonPositive, at: b.date().to_string(), detail: "a price is zero or negative".to_string() });
        } else if b.high.minor < b.low.minor || b.close.minor > b.high.minor || b.close.minor < b.low.minor || b.open.minor > b.high.minor || b.open.minor < b.low.minor {
            problems.push(SeriesProblem { kind: SeriesProblemKind::ImpossibleBar, at: b.date().to_string(), detail: "open/close outside high/low, or high below low".to_string() });
        }

        if let Some(p) = prev {
            if p.close.minor > 0 {
                let move_ = (b.close.minor - p.close.minor) as f64 / p.close.minor as f64;
                // A 2-for-1 split is −50%. In a series that says it is adjusted this is a real move;
                // in one that says it is not, it is almost certainly a corporate action, and a
                // strategy that buys drops will find a great many of them.
                if meta.adjusted == Some(false) && move_.abs() >= opts.split_move {
                    problems.push(SeriesProblem {
                        kind: SeriesProblemKind::ProbableCorporateAction,
                        at: b.date().to_string(),
                        detail: format!("{}% in one day in a series declared UNADJUSTED — a split or a distribution, not a return", (move_ * 100.0).round()),
                    });
                }
            }
            // A missing WEEKDAY. Without an exchange calendar this cannot tell a holiday from a
            // hole, and saying so is better than a silent false positive on every public holiday.
            let mut d = next_day(p.date());
            while d.as_str() < b.date() {
                if !is_weekend(&d) && !opts.holidays.contains(&d) {
                    problems.push(SeriesProblem {
                        kind: SeriesProblemKind::Gap,
                        at: d.clone(),
                        detail: "no bar on a weekday — a market holiday if a calendar says so, a hole in the data if not".to_string(),
                    });
                }
                let next = next_day(&d);
                if next == d {
                    break; // an unparseable date would otherwise spin here
                }
                d = next;
            }
        }
    }

    let mut run = 1usize;
    for i in 1..bars.len() {
        if bars[i].close.minor == bars[i - 1].close.minor {
            run += 1;
            // EXACTLY at the threshold, once — not on every identical close after it, which would
            // bury the finding under its own repetition.
            if run == opts.stale_run {
                problems.push(SeriesProblem {
                    kind: SeriesProblemKind::Stale,
                    at: bars[i].date().to_string(),
                    detail: format!("{} identical closes in a row — a dead feed and a genuinely flat market are indistinguishable here", opts.stale_run),
                });
            }
        } else {
            run = 1;
        }
    }

    let ok = problems.is_empty() && !bars.is_empty();
    SeriesCheck {
        series: if ok { Some(VerifiedSeries { bars: bars.to_vec(), meta, unverified: false, caveat: None }) } else { None },
        ok,
        problems,
    }
}

/// A series accepted WITHOUT the check, because refusing outright makes a system nobody uses.
///
/// Deliberately ugly: it demands a reason, marks the series, and its name is greppable — so "which
/// of these results rest on unchecked data?" has an answer.
pub fn unverified_series(bars: &[Bar], meta: SeriesMeta, caveat: &str) -> Result<VerifiedSeries, String> {
    if caveat.trim().is_empty() {
        return Err("an unverified series must say why it could not be checked".to_string());
    }
    Ok(VerifiedSeries { bars: bars.to_vec(), meta, unverified: true, caveat: Some(caveat.to_string()) })
}

/// THE LOOK-AHEAD GUARD, and the most important function here.
///
/// Everything you could have known when deciding on `date` — which is every bar STRICTLY BEFORE it.
/// Not up to and including: on the morning of a decision, that day's high, low and close do not
/// exist yet, and a backtest that reads them produces an equity curve that cannot be traded.
///
/// Written as the only supported way to slice a series for a decision, so the wrong thing takes
/// deliberate effort rather than merely being discouraged in a comment.
pub fn bars_available_at<'a>(s: &'a VerifiedSeries, date: &str) -> &'a [Bar] {
    let n = s.bars.partition_point(|b| b.date() < date);
    &s.bars[..n]
}

/// The most recent bar that existed BEFORE a decision date, if any.
pub fn last_bar_before<'a>(s: &'a VerifiedSeries, date: &str) -> Option<&'a Bar> {
    bars_available_at(s, date).last()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UniverseClaim {
    pub allowed: bool,
    pub why: String,
}

/// Whether a UNIVERSE-level claim may be made from this series.
///
/// "This strategy beats the index" is a claim about a universe, and it is meaningless on a series
/// that has not declared itself survivorship-free — the losers are missing and nothing in the data
/// says so. Single-instrument claims are unaffected.
pub fn may_make_universe_claim(s: &VerifiedSeries) -> UniverseClaim {
    match s.meta.survivorship_free {
        Some(true) => UniverseClaim { allowed: true, why: "the universe declares it includes delisted names".to_string() },
        Some(false) => UniverseClaim {
            allowed: false,
            why: "the universe EXCLUDES delisted names — every company that went to zero is missing, and no result computed across it is comparable to an index".to_string(),
        },
        None => UniverseClaim {
            allowed: false,
            why: "nobody declared whether this universe includes delisted names, and it cannot be inferred from the data — absent is not the same as false, and neither is safe to build a universe claim on".to_string(),
        },
    }
}

/// One line stating what a result rests on.
pub fn provenance(s: &VerifiedSeries) -> String {
    let adj = match s.meta.adjusted {
        Some(true) => "adjusted",
        Some(false) => "UNADJUSTED",
        None => "adjustment UNDECLARED",
    };
    let base = format!("{} · {} bar(s) · {adj} · {}", s.meta.symbol, s.bars.len(), s.meta.source);
    match &s.caveat {
        Some(c) if s.unverified => format!("UNVERIFIED — {c} · {base}"),
        _ => format!("checked · {base}"),
    }
}

/// Simple return between two bars, as a fraction. NONE where the base is not a price.
pub fn period_return(from: &Bar, to: &Bar) -> Option<f64> {
    if from.close.minor <= 0 {
        return None;
    }
    Some((to.close.minor - from.close.minor) as f64 / from.close.minor as f64)
}

/// Build a price at the series' declared scale, so a caller cannot silently mix scales.
pub fn price(units: f64, meta: &SeriesMeta, currency: Currency) -> Money {
    money((units * meta.minor_per_unit as f64).round() as i64, currency)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY — no real market data reaches this repo.
    fn bar(date: &str, o: i64, h: i64, l: i64, c: i64) -> Bar {
        Bar { date_i: BarDate::new(date), open: usd(o), high: usd(h), low: usd(l), close: usd(c), volume: None }
    }

    fn meta() -> SeriesMeta {
        SeriesMeta::new("ACME", "test")
    }

    fn clean() -> Vec<Bar> {
        vec![bar("2026-06-01", 1_000, 1_010, 990, 1_005), bar("2026-06-02", 1_005, 1_020, 1_000, 1_015), bar("2026-06-03", 1_015, 1_025, 1_010, 1_020)]
    }

    fn kinds(c: &SeriesCheck) -> Vec<(&'static str, &str)> {
        c.problems.iter().map(|p| (p.kind.label(), p.at.as_str())).collect()
    }

    #[test]
    fn the_look_ahead_guard_hands_back_only_what_existed_before_the_decision() {
        let s = check_series(&clean(), meta(), &CheckOptions::default()).series.expect("clean");
        // STRICTLY before. On the morning of the 2nd, the 2nd's close does not exist yet — and a
        // backtest that reads it produces an equity curve nobody could have traded.
        assert_eq!(bars_available_at(&s, "2026-06-02").iter().map(|b| b.date()).collect::<Vec<_>>(), vec!["2026-06-01"]);
        assert_eq!(bars_available_at(&s, "2026-06-03").iter().map(|b| b.date()).collect::<Vec<_>>(), vec!["2026-06-01", "2026-06-02"]);
        assert_eq!(last_bar_before(&s, "2026-06-03").map(|b| b.date()), Some("2026-06-02"));
        // Before the series starts there is nothing, which is ABSENT rather than the first bar.
        assert!(last_bar_before(&s, "2026-06-01").is_none());
        assert!(bars_available_at(&s, "2026-06-01").is_empty());
        // And a date past the end sees everything.
        assert_eq!(bars_available_at(&s, "2030-01-01").len(), 3);
    }

    #[test]
    fn a_raw_vector_cannot_become_a_verified_series() {
        // The fields are PRIVATE, so this module is the only place one is built. That is the whole
        // enforcement, and it is stronger than the TypeScript's phantom symbol, which a cast forges.
        let bad = vec![bar("2026-06-01", 1_000, 1_010, 990, 0)];
        let c = check_series(&bad, meta(), &CheckOptions::default());
        assert!(!c.ok);
        assert!(c.series.is_none(), "a failing check mints NOTHING");
    }

    #[test]
    fn each_way_a_series_lies_is_caught_and_named() {
        // Every row measured by running finance-series.ts.
        let d = CheckOptions::default();
        assert_eq!(kinds(&check_series(&[bar("2026-06-01", 1_000, 1_010, 990, 1_005), bar("2026-06-01", 1_005, 1_020, 1_000, 1_015)], meta(), &d)), vec![("duplicate", "2026-06-01")]);
        assert_eq!(kinds(&check_series(&[bar("2026-06-02", 1_000, 1_010, 990, 1_005), bar("2026-06-01", 1_005, 1_020, 1_000, 1_015)], meta(), &d)), vec![("out-of-order", "2026-06-01")]);
        assert_eq!(kinds(&check_series(&[bar("2026-06-01", 1_000, 1_010, 0, 1_005)], meta(), &d)), vec![("non-positive", "2026-06-01")]);
        assert_eq!(kinds(&check_series(&[bar("2026-06-01", 1_000, 900, 990, 1_005)], meta(), &d)), vec![("impossible-bar", "2026-06-01")]);
    }

    #[test]
    fn a_missing_weekday_is_a_gap_and_a_weekend_is_not() {
        let d = CheckOptions::default();
        let across = [bar("2026-06-01", 1_000, 1_010, 990, 1_000), bar("2026-06-04", 1_000, 1_010, 990, 1_000)];
        assert_eq!(kinds(&check_series(&across, meta(), &d)), vec![("gap", "2026-06-02"), ("gap", "2026-06-03")]);
        // Told which days the market was shut, it says nothing — it cannot tell a holiday from a
        // hole on its own, and it does not pretend to.
        let holidays = ["2026-06-02".to_string(), "2026-06-03".to_string()];
        assert!(check_series(&across, meta(), &CheckOptions { holidays: &holidays, ..CheckOptions::default() }).ok);
        // Friday to Monday is not a gap. 2026-06-05 IS a Friday and 2026-06-08 a Monday.
        let weekend = [bar("2026-06-05", 1_000, 1_010, 990, 1_000), bar("2026-06-08", 1_000, 1_010, 990, 1_000)];
        assert!(check_series(&weekend, meta(), &d).ok);
        assert!(is_weekend("2026-06-06") && is_weekend("2026-06-07"));
        assert!(!is_weekend("2026-06-05") && !is_weekend("2026-06-08"));
    }

    #[test]
    fn a_repeating_feed_is_reported_once_rather_than_on_every_identical_close() {
        let stale: Vec<Bar> = ["2026-06-01", "2026-06-02", "2026-06-03", "2026-06-04", "2026-06-05", "2026-06-08", "2026-06-09"]
            .iter()
            .map(|d| bar(d, 1_000, 1_010, 990, 1_000))
            .collect();
        // Fires EXACTLY at the fifth identical close and not again — a finding repeated seven times
        // is buried under itself.
        assert_eq!(kinds(&check_series(&stale, meta(), &CheckOptions::default())), vec![("stale", "2026-06-05")]);
        // A dead feed and a genuinely flat market are indistinguishable, and the detail says so
        // rather than asserting which one it is.
        let p = &check_series(&stale, meta(), &CheckOptions::default()).problems[0];
        assert!(p.detail.contains("indistinguishable"));
    }

    #[test]
    fn a_split_shaped_move_is_a_corporate_action_only_where_the_series_says_it_is_unadjusted() {
        let split = [bar("2026-06-01", 2_000, 2_010, 1_990, 2_000), bar("2026-06-02", 1_000, 1_010, 990, 1_000)];
        let d = CheckOptions::default();
        let unadj = SeriesMeta { adjusted: Some(false), ..meta() };
        assert_eq!(kinds(&check_series(&split, unadj, &d)), vec![("probable-corporate-action", "2026-06-02")]);
        // In a series that says it IS adjusted, −50% is a real move and reporting it would be noise.
        assert!(check_series(&split, SeriesMeta { adjusted: Some(true), ..meta() }, &d).ok);
        // UNDECLARED is not the same as false — nothing is claimed either way.
        assert!(check_series(&split, meta(), &d).ok);
    }

    #[test]
    fn a_universe_claim_is_refused_unless_survivorship_was_declared() {
        let c = clean();
        let claim = |v: Option<bool>| may_make_universe_claim(&unverified_series(&c, SeriesMeta { survivorship_free: v, ..meta() }, "x").expect("caveat given"));
        assert!(claim(Some(true)).allowed);
        assert!(!claim(Some(false)).allowed);
        assert!(claim(Some(false)).why.contains("every company that went to zero is missing"));
        // ABSENT IS NOT FALSE, and neither is safe to build a universe claim on.
        let undeclared = claim(None);
        assert!(!undeclared.allowed);
        assert!(undeclared.why.contains("absent is not the same as false"));
    }

    #[test]
    fn an_unverified_series_must_say_why_and_carries_it_into_every_provenance() {
        let c = clean();
        assert_eq!(unverified_series(&c, meta(), "  ").unwrap_err(), "an unverified series must say why it could not be checked");
        let u = unverified_series(&c, meta(), "the source could not be checked").expect("a caveat");
        assert!(u.unverified());
        assert_eq!(provenance(&u), "UNVERIFIED — the source could not be checked · ACME · 3 bar(s) · adjustment UNDECLARED · test");
    }

    #[test]
    fn the_provenance_states_the_adjustment_because_a_result_depends_on_it() {
        let c = clean();
        let d = CheckOptions::default();
        let p = |m: SeriesMeta| provenance(&check_series(&c, m, &d).series.expect("clean"));
        assert_eq!(p(meta()), "checked · ACME · 3 bar(s) · adjustment UNDECLARED · test");
        assert_eq!(p(SeriesMeta { adjusted: Some(true), ..meta() }), "checked · ACME · 3 bar(s) · adjusted · test");
        assert_eq!(p(SeriesMeta { adjusted: Some(false), ..meta() }), "checked · ACME · 3 bar(s) · UNADJUSTED · test");
    }

    #[test]
    fn an_empty_series_is_not_ok_and_has_nothing_to_complain_about() {
        let c = check_series(&[], meta(), &CheckOptions::default());
        assert!(!c.ok, "there is nothing here to build on");
        assert!(c.problems.is_empty(), "and nothing is WRONG with it either — it is simply empty");
        assert!(c.series.is_none());
    }

    #[test]
    fn returns_and_prices_stay_at_the_declared_scale() {
        let c = clean();
        assert_eq!(period_return(&c[0], &c[2]), Some(0.014925373134328358));
        // A zero base is not a price, so the return is ABSENT rather than infinite.
        assert_eq!(period_return(&bar("x", 0, 0, 0, 0), &c[0]), None);
        assert_eq!(price(12.345, &meta(), Currency::USD).minor, 1_235);
        assert_eq!(price(10.0, &meta(), Currency::USD).minor, 1_000);
        // A different scale is a different number of minor units for the same quoted price.
        let tenths = SeriesMeta { minor_per_unit: 1_000, ..meta() };
        assert_eq!(price(10.0, &tenths, Currency::USD).minor, 10_000);
    }

    #[test]
    fn a_bar_date_survives_being_held_inline() {
        assert_eq!(BarDate::new("2026-06-01").as_str(), "2026-06-01");
        assert!(BarDate::new("2026-06-01") < BarDate::new("2026-06-02"));
        assert!(BarDate::new("2025-12-31") < BarDate::new("2026-01-01"));
        // Padding never turns one date into another.
        assert_ne!(BarDate::new("2026-06-01"), BarDate::new("2026-06-10"));
        assert_eq!(BarDate::new("2026-06-01").to_string(), "2026-06-01");
    }
}
